  "config_parse_once": {
    title: "parse_argv checks the port once, and Config carries the proof",
    expectPython: "passes",
    expectTypescript: "passes",
    runs: false,
    improves: "config_validate_everywhere",
    misuseOf: null,
    python: "from dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Config:\n    port: int\n    verbose: bool\n\n\ndef parse_argv(argv: list[str]) -> Config:\n    settings: dict[str, str] = {}\n    for pair in argv:\n        key, _, value = pair.partition(\"=\")\n        settings[key] = value\n    port_text = settings.get(\"port\")\n    if port_text is None or not port_text.isdigit():\n        raise ValueError(\"port missing or not a number\")\n    verbose_text = settings.get(\"verbose\", \"false\")\n    if verbose_text not in (\"true\", \"false\"):\n        raise ValueError(\"verbose must be true or false\")\n    return Config(port=int(port_text), verbose=verbose_text == \"true\")\n\n\ndef connect(config: Config) -> str:\n    return f\"connecting on {config.port}\"  # no check, and none needed\n\n\ndef report(config: Config) -> str:\n    return f\"listening on {config.port}\"\n",
    typescript: "type Config = {\n  readonly port: number;\n  readonly verbose: boolean;\n};\n\nexport function parseArgv(argv: string[]): Config {\n  const settings = new Map<string, string>();\n  for (const pair of argv) {\n    const [key, value] = pair.split(\"=\", 2);\n    settings.set(key ?? \"\", value ?? \"\");\n  }\n  const portText = settings.get(\"port\");\n  if (portText === undefined || !/^\\d+$/.test(portText)) {\n    throw new Error(\"port missing or not a number\");\n  }\n  const verboseText = settings.get(\"verbose\") ?? \"false\";\n  if (verboseText !== \"true\" && verboseText !== \"false\") {\n    throw new Error(\"verbose must be true or false\");\n  }\n  return { port: Number(portText), verbose: verboseText === \"true\" };\n}\n\nexport function connect(config: Config): string {\n  return `connecting on ${config.port}`; // no check, and none needed\n}\n\nexport function report(config: Config): string {\n  return `listening on ${config.port}`;\n}\n",
  },
