    python: "from collections.abc import Callable\nfrom typing import Any\n\n\ndef retry(times: int, operation: Callable[..., Any]) -> Callable[..., Any]:\n    def attempt(*args: Any, **kwargs: Any) -> Any:\n        failures = 0\n        while True:\n            try:\n                return operation(*args, **kwargs)\n            except ConnectionError:\n                failures += 1\n                if failures >= times:\n                    raise\n    return attempt\n\n\ndef fetch(url: str, timeout: int) -> str:\n    return f\"GET {url} within {timeout}s\"\n\n\npatient_fetch = retry(3, fetch)\nfine = patient_fetch(\"https://example.test\", 10)\nwrong = patient_fetch(10, \"https://example.test\")  # accepted, and wrong\n",
    typescript: "function retry(times: number, operation: (...args: any[]) => any): (...args: any[]) => any {\n  return (...args: any[]) => {\n    let failures = 0;\n    for (;;) {\n      try {\n        return operation(...args);\n      } catch (error) {\n        failures += 1;\n        if (failures >= times) throw error;\n      }\n    }\n  };\n}\n\nfunction fetchPage(url: string, timeout: number): string {\n  return `GET ${url} within ${timeout}s`;\n}\n\nconst patientFetch = retry(3, fetchPage);\nexport const fine = patientFetch(\"https://example.test\", 10);\nexport const wrong = patientFetch(10, \"https://example.test\"); // accepted, and wrong\n",
