  "io_actions": {
    python: "--- a/example.py\n+++ b/example.py\n@@ -1,13 +1,46 @@\n-def fetch_greeting(attempts_left: int = 3) -> str:\n-    failures = 0\n-    while True:\n-        try:\n-            return unreliable_fetch().upper()\n-        except ConnectionError:\n-            failures += 1\n-            if failures >= attempts_left:\n-                raise\n+from collections.abc import Callable\n+from dataclasses import dataclass\n+\n+\n+@dataclass(frozen=True)\n+class IO[T]:\n+    run: Callable[[], T]\n+\n+\n+def of[T](value: T) -> IO[T]:\n+    return IO(lambda: value)\n+\n+\n+def and_then[T, U](action: IO[T], step: Callable[[T], IO[U]]) -> IO[U]:\n+    return IO(lambda: step(action.run()).run())\n \n \n-def unreliable_fetch() -> str:\n-    raise ConnectionError(\"try again\")\n+def retry[T](times: int, action: IO[T]) -> IO[T]:\n+    def attempt() -> T:\n+        failures = 0\n+        while True:\n+            try:\n+                return action.run()\n+            except ConnectionError:\n+                failures += 1\n+                if failures >= times:\n+                    raise\n+    return IO(attempt)\n+\n+\n+# A connection that fails twice and then answers, so the retry is observable.\n+_calls = {\"count\": 0}\n+\n+\n+def flaky_fetch() -> str:\n+    _calls[\"count\"] += 1\n+    if _calls[\"count\"] < 3:\n+        raise ConnectionError(\"try again\")\n+    return \"payload\"\n+\n+\n+greeting = and_then(retry(3, IO(flaky_fetch)), lambda text: of(text.upper()))\n+\n+assert _calls[\"count\"] == 0  # nothing has run yet\n+assert greeting.run() == \"PAYLOAD\"\n+assert _calls[\"count\"] == 3  # two failures, one answer\n",
    typescript: "--- a/example.ts\n+++ b/example.ts\n@@ -1,18 +1,41 @@\n class ConnectionLost extends Error {}\n \n-function unreliableFetch(): string {\n-  throw new ConnectionLost(\"try again\");\n+type IO<T> = { readonly run: () => T };\n+\n+function of<T>(value: T): IO<T> {\n+  return { run: () => value };\n }\n \n-export function fetchGreeting(attemptsLeft = 3): string {\n-  let failures = 0;\n-  for (;;) {\n-    try {\n-      return unreliableFetch().toUpperCase();\n-    } catch (error) {\n-      if (!(error instanceof ConnectionLost)) throw error;\n-      failures += 1;\n-      if (failures >= attemptsLeft) throw error;\n-    }\n-  }\n+function andThen<T, U>(action: IO<T>, step: (value: T) => IO<U>): IO<U> {\n+  return { run: () => step(action.run()).run() };\n }\n+\n+function retry<T>(times: number, action: IO<T>): IO<T> {\n+  return {\n+    run: () => {\n+      let failures = 0;\n+      for (;;) {\n+        try {\n+          return action.run();\n+        } catch (error) {\n+          if (!(error instanceof ConnectionLost)) throw error;\n+          failures += 1;\n+          if (failures >= times) throw error;\n+        }\n+      }\n+    },\n+  };\n+}\n+\n+// A connection that fails twice and then answers, so the retry is observable.\n+let calls = 0;\n+\n+function flakyFetch(): string {\n+  calls += 1;\n+  if (calls < 3) throw new ConnectionLost(\"try again\");\n+  return \"payload\";\n+}\n+\n+export const greeting = andThen(retry(3, { run: flakyFetch }), (text) => of(text.toUpperCase()));\n+// Nothing has run yet; greeting.run() answers \"PAYLOAD\" on the third call.\n+// The Python twin runs these assertions in CI.\n",
  },
